from pathlib import Path
import subprocess, json, time, re, sys, signal, xml.etree.ElementTree as ET
state=Path(__file__).parent
serial='100.76.86.48:5555';pkg='dev.waterui.hydrolysis.opacity3323'
repo=Path('/Users/lexoliu/Coding/cherenkov-benchmarks-worktrees/fair-runners')
sys.path.insert(0,str(repo/'scripts'))
from sync_runs import RunArchive,publish
out=state/('3490-device-'+sys.argv[1]);out.mkdir(exist_ok=False)
def adb(*args,timeout=40):return subprocess.check_output(['adb','-s',serial,*args],timeout=timeout)
def text(*args):return adb(*args).decode().strip()
def terminate(*_):raise SystemExit('device deadline reached')
signal.signal(signal.SIGTERM,terminate)
backups=[]
installed_before=('package:'+pkg) in text('shell','pm','list','packages',pkg).splitlines()
for i,line in enumerate(text('shell','pm','path',pkg).splitlines() if installed_before else []):
 p=out/f'previous-{i}.apk';adb('pull',line.removeprefix('package:'),str(p),timeout=60);backups.append(str(p))
awake='mWakefulness=Awake' in text('shell','dumpsys','power')
old_timeout=text('shell','settings','get','system','screen_off_timeout')
runs=[];installed=False
metadata={'device':{'model':text('shell','getprop','ro.product.model'),'model_identifier':text('shell','getprop','ro.product.device'),'os':'Android '+text('shell','getprop','ro.build.version.release'),'gpu':'Mali-G715'},'configuration':{'measurement_kind':'pipeline-cache-fresh-process-diagnostic','comparison':'ABBA, each install has a priming launch followed by a measured fresh process; cache is retained across installs; first-ever empty-cache cost is not established','scene':'opacity3323','metrics':'native tile pipeline creation, device timestamp before am-start to first idle-present log (includes adb and launch overhead), process memory; diagnostic, not frame p99'},'source':{'revision':'c40115e8374f97990997fdaad15fc61144fe2bbc'}}
journals={}
try:
 adb('shell','settings','put','system','screen_off_timeout','300000');adb('shell','input','keyevent','KEYCODE_WAKEUP');adb('shell','wm','dismiss-keyguard')
 for index,arm in enumerate(['baseline','candidate','candidate','baseline']):
  result=text('install','-r','-d',str(state/f'3490-{arm}.apk'))
  if 'Success' not in result:raise RuntimeError(result)
  installed=True
  for launch in ['prime','measured']:
   name=f'{index}-{arm}-{launch}'
   stamp=text('shell',"date '+%m-%d %H:%M:%S.000'")
   start=float(text('shell','date','+%s.%N'));am=text('shell','am','start','-W','-S','-n',pkg+'/dev.waterui.hydrolysis.testapp.MainActivity','--es','waterui.log.level','INFO')
   time.sleep(5)
   pid=text('shell','pidof',pkg)
   adb('shell','uiautomator','dump','/sdcard/3490-ui.xml')
   xml=text('shell','cat','/sdcard/3490-ui.xml');buttons={}
   for node in ET.fromstring(xml).iter('node'):
    label=node.get('text','')+' '+node.get('content-desc','')
    if 'Fade for six seconds' in label:
     x0,y0,x1,y1=map(int,re.findall(r'\d+',node.attrib['bounds']));buttons['fade']=((x0+x1)//2,(y0+y1)//2)
   if 'fade' not in buttons:raise RuntimeError('fade button absent')
   if launch=='measured':(out/(name+'-initial.png')).write_bytes(adb('exec-out','screencap','-p'))
   events=[]
   for fade in range(2):
    events.append({'event':f'fade-{fade}','epoch':float(text('shell','date','+%s.%N'))});adb('shell','input','tap',*map(str,buttons['fade']));time.sleep(1)
    if launch=='measured':(out/(name+f'-fade-{fade}.png')).write_bytes(adb('exec-out','screencap','-p'))
    time.sleep(7)
   log=adb('logcat','-d','-v','epoch','--pid='+pid,'-T',stamp).decode(errors='replace')
   memory=text('shell','dumpsys','meminfo',pkg)
   (out/(name+'.log')).write_text(log);(out/(name+'-memory.txt')).write_text(memory)
   if 'panic at ' in log:raise RuntimeError('app panic')
   if text('shell','pidof',pkg)!=pid:raise RuntimeError('process changed')
   runs.append({'name':name,'arm':arm,'launch':launch,'launch_epoch':start,'launch_output':am,'events':events,'log':log.splitlines(),'memory':memory})
   (out/'runs.json').write_text(json.dumps(runs,indent=2))
   print('completed',name,flush=True)
finally:
 if installed:
  adb('shell','am','force-stop',pkg)
  if backups:adb('install' if len(backups)==1 else 'install-multiple','-r','-d',*backups,timeout=120)
 adb('shell','rm','-f','/sdcard/3490-ui.xml')
 if old_timeout=='null':adb('shell','settings','delete','system','screen_off_timeout')
 else:adb('shell','settings','put','system','screen_off_timeout',old_timeout)
 if not awake:adb('shell','input','keyevent','KEYCODE_SLEEP')
 for i,run in enumerate(runs):
  artifact=out/f'run-{i}.json';artifact.write_text(json.dumps({'engine':'cherenkov','scene':'opacity3323','width':None,'height':None,'samples':[],'diagnostic':run,'runner_source':Path(__file__).read_text(),'revision':'8994e3e93d1cb49f645188861f315779c490ca7c' if run['arm']=='baseline' else 'c40115e8374f97990997fdaad15fc61144fe2bbc','instrumentation_patch':(state/f"3490-{run['arm']}-diagnostic.patch").read_text()}))
  run_metadata={**metadata,'source':{'revision':'8994e3e93d1cb49f645188861f315779c490ca7c' if run['arm']=='baseline' else 'c40115e8374f97990997fdaad15fc61144fe2bbc'}}
  journal=RunArchive(out/('journal-'+run['arm']),run_metadata);journals[run['arm']]=journal
  journal.record(artifact,{},valid=False,reason='Fresh-process compilation diagnostic, not steady frame timing, p99, or cross-engine ranking.')
 for journal in journals.values():publish(journal.directory,repo)
